package bili

import (
	"bufio"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// defaultCookieDomain 是二维码登录拿到的 cookie 没带 Domain 时补的域。
const defaultCookieDomain = ".bilibili.com"

// 文件头保持纯 ASCII：yt-dlp 用 python 读 cookies，编码不一定按 UTF-8 来。
const netscapeFileHeader = "# Netscape HTTP Cookie File\n" +
	"# Generated by bili-subtitle. Treat this file like a password.\n\n"

// LoadCookiesFile 读 Netscape 格式 cookies.txt，返回 name->value；文件不存在返回空 map 和 nil。
func LoadCookiesFile(path string) (map[string]string, error) {
	file, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return map[string]string{}, nil
		}
		return nil, fmt.Errorf("打开 cookies 文件失败：%w", err)
	}
	defer file.Close()

	cookies := make(map[string]string)
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 64<<10), 1<<20)
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		// curl 和浏览器导出工具把 HttpOnly cookie 的域名写成 "#HttpOnly_.bilibili.com"。
		if strings.HasPrefix(line, "#HttpOnly_") {
			line = strings.TrimPrefix(line, "#HttpOnly_")
		} else if strings.HasPrefix(line, "#") {
			continue
		}
		// Netscape 标准用制表符分隔：domain flag path secure expires name value。
		fields := strings.Split(line, "\t")
		if len(fields) < 7 {
			continue // 单行坏了不影响整个文件，继续往下读
		}
		name := fields[5]
		value := strings.Join(fields[6:], "\t")
		if name == "" {
			continue
		}
		cookies[name] = value
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("读取 cookies 文件失败（约第 %d 行）：%w", lineNo, err)
	}
	return cookies, nil
}

// SaveCookiesFile 把 http.Cookie 列表以 Netscape 格式写到 path（自动建目录），返回 name->value。
func SaveCookiesFile(path string, cookies []*http.Cookie) (map[string]string, error) {
	if strings.TrimSpace(path) == "" {
		return nil, fmt.Errorf("保存 cookies 失败：文件路径为空")
	}
	if dir := filepath.Dir(path); dir != "" && dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return nil, fmt.Errorf("保存 cookies 失败：创建目录 %s 出错：%w", dir, err)
		}
	}

	var builder strings.Builder
	builder.WriteString(netscapeFileHeader)
	result := make(map[string]string, len(cookies))
	for _, cookie := range cookies {
		if cookie == nil || cookie.Name == "" {
			continue
		}
		// 值里混进制表符或换行会把 Netscape 的列拆坏；B 站的 cookie 值不会出现这些字符，直接清掉。
		value := strings.NewReplacer("\t", "", "\r", "", "\n", "").Replace(cookie.Value)
		domain := strings.TrimSpace(cookie.Domain)
		if domain == "" {
			domain = defaultCookieDomain
		}
		includeSubdomains := "FALSE"
		if strings.HasPrefix(domain, ".") {
			includeSubdomains = "TRUE"
		}
		cookiePath := cookie.Path
		if cookiePath == "" {
			cookiePath = "/"
		}
		secure := "FALSE"
		if cookie.Secure {
			secure = "TRUE"
		}
		expires := int64(0)
		if !cookie.Expires.IsZero() {
			expires = cookie.Expires.Unix()
		}
		fmt.Fprintf(&builder, "%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
			domain, includeSubdomains, cookiePath, secure, strconv.FormatInt(expires, 10), cookie.Name, value)
		result[cookie.Name] = value
	}

	// 先写临时文件再改名，中途失败不会留下半截 cookies 文件。
	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, []byte(builder.String()), 0o600); err != nil {
		return nil, fmt.Errorf("保存 cookies 失败：写临时文件 %s 出错：%w", tmpPath, err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		_ = os.Remove(tmpPath)
		return nil, fmt.Errorf("保存 cookies 失败：重命名到 %s 出错：%w", path, err)
	}
	return result, nil
}
